using System;using System.Collections.Generic;using System.IO;using Ashfall.Core;using Ashfall.Modules.Networking;using Ashfall.Modules.HealthStates;using Ashfall.Integration.Playable.Explosives;using Ashfall.Integration.Playable.HandsWeapons;
namespace Ashfall.Integration.Playable.Networking {
 public interface IR24LanProjectileWorld {bool Sweep(Float3 from,Float3 to,float radius,out float distance,out Float3 normal);}
 public sealed class R24LanGrenadeState {public readonly string Id,Kind,Owner;public readonly Float3 Position;public readonly bool Spent;public readonly long Revision;internal R24LanGrenadeState(string id,string kind,string owner,Float3 at,bool spent,long revision){Id=id;Kind=kind;Owner=owner;Position=at;Spent=spent;Revision=revision;}}
 public sealed class R24LanProjectileState {public readonly string Id,Kind;public readonly Float3 Position,Velocity;public readonly float Age,Radius,EmitAt;public readonly bool Active,Ended;public readonly long Revision;internal R24LanProjectileState(string id,string kind,Float3 at,Float3 velocity,float age,float radius,bool active,bool ended,long revision):this(id,kind,at,velocity,age,radius,active,ended,revision,-1){}internal R24LanProjectileState(string id,string kind,Float3 at,Float3 velocity,float age,float radius,bool active,bool ended,long revision,float emitAt){Id=id;Kind=kind;Position=at;Velocity=velocity;Age=age;Radius=radius;Active=active;Ended=ended;Revision=revision;EmitAt=emitAt;}}
 public sealed partial class R24LanLobby {
  const string GrenadeFeature="playable.grenade/1",GrenadeCommand="playable.grenade.command/1",RocketCommand="playable.rocket.launch/1",ProjectileFeature="playable.projectile/1";
  IR24LanProjectileWorld projectileWorld;long grenadeSequence,projectileSequence,projectileIds;double nextProjectiles;
  readonly Dictionary<string,R24LanGrenadeState> grenades=new Dictionary<string,R24LanGrenadeState>(StringComparer.Ordinal);
  sealed class GrenadeOwner {internal readonly R23GrenadeState State=new R23GrenadeState();internal double At;internal long Life=-1;}
  readonly Dictionary<string,GrenadeOwner> grenadeOwners=new Dictionary<string,GrenadeOwner>(StringComparer.Ordinal);
  sealed class Projectile {internal string Id,Kind,Actor;internal int Team;internal Float3 At,Velocity;internal float Age,Power,Roll;internal double Time;internal R23GrenadeClock Clock;}
  readonly Dictionary<string,Projectile> projectiles=new Dictionary<string,Projectile>(StringComparer.Ordinal);readonly Dictionary<string,R24LanProjectileState> projectileStates=new Dictionary<string,R24LanProjectileState>(StringComparer.Ordinal);
  public R24LanGrenadeState[] SharedGrenades{get{return CopySnapshot(grenades.Values);}}public R24LanProjectileState[] SharedProjectiles{get{return CopySnapshot(projectileStates.Values);}}
  public string LastExplosiveRejection{get;private set;}
  // flashsmoke: replicated kill switches; frag/zone/smaw are never gated here.
  bool ThrowableAllowed(string kind){var rules=roundRules;return rules==null||Ashfall.Integration.Playable.FlashSmoke.R25Throwables.Allowed(kind,rules.Flashbangs,rules.SmokeGrenades);}
  // flashsmoke: only smoke rows carry the emission start (launch-relative s, -1 before emission).
  static bool ProjectileEmitValid(string kind,float emitAt,float age){if(kind!=Ashfall.Integration.Playable.FlashSmoke.R25Throwables.Smoke)return emitAt==-1;return emitAt==-1||!Single.IsNaN(emitAt)&&emitAt>=0&&emitAt<=Ashfall.Integration.Playable.FlashSmoke.R25SmokeCloud.LaunchDelay+.001f&&emitAt<=age+.001f;}
  public void BindProjectileWorld(IR24LanProjectileWorld world){Check();if(State!=R24LanLobbyState.Hosting||world==null||projectileWorld!=null)throw new InvalidOperationException("One host projectile sweep world");projectileWorld=world;}
  void ClearExplosives(){grenades.Clear();grenadeOwners.Clear();projectiles.Clear();projectileStates.Clear();nextProjectiles=0;receivedProjectileSequence=-1;foreach(var peer in peers.Values){peer.Grenades.Clear();peer.Projectiles.Clear();}}
  public bool RegisterSharedGrenade(string id,string kind,Float3 at){Check();if(State!=R24LanLobbyState.Hosting||SelectedMap==null||SelectedMap.Cancelled||!Wire.IsText(id,128,false)||!R23GrenadeState.ValidKind(kind)||!ThrowableAllowed(kind)||!at.IsFinite||grenades.ContainsKey(id)||grenades.Count>=4096)return false;PublishGrenade(id,kind,"",at,false);return true;}
  public bool TryReadGrenade(string id,out R24LanGrenadeState state){Check();state=null;return id!=null&&grenades.TryGetValue(id,out state);}
  int WeaponSlots(CombatActor actor){int count=0;foreach(var weapon in actor.Weapons.Values)if(weapon.Profile!="smaw"||weapon.Ammo>0||weapon.RocketReloads>0)count++;return count;}
  int GrenadeSlots(string actor){GrenadeOwner owner;if(!grenadeOwners.TryGetValue(actor,out owner))return 0;var slots=new HashSet<int>();foreach(var item in owner.State.OwnedItems)slots.Add(item.Slot);return slots.Count;}
  bool GrenadeHandOccupied(string actor,int hand){GrenadeOwner owner;return grenadeOwners.TryGetValue(actor,out owner)&&owner.State.HeldId!=null&&owner.State.HeldHand==hand+1;}
  GrenadeOwner OwnerGrenades(string actor,CombatActor inventory){GrenadeOwner owner;if(!grenadeOwners.TryGetValue(actor,out owner)){owner=new GrenadeOwner{At=clock.Now};grenadeOwners[actor]=owner;}var member=sessions.Get(actor);var health=member==null?null:hostHealth.Read(member.CanonicalActorId);if(health==null||health.LifeGeneration!=owner.Life){owner.State.Stow();owner.Life=health==null?-1:health.LifeGeneration;}double dt=Math.Max(0,clock.Now-owner.At);owner.At=clock.Now;owner.State.Advance((float)Math.Min(.25,dt));owner.State.SlotCapacity=inventory.Capacity;owner.State.SetOtherSlotsUsed(WeaponSlots(inventory)+FoodSlots(actor));return owner;}
  public bool RequestGrenade(string id,int hand,int action,Float3 at){Check();if(!Wire.IsText(id,128,false)||hand<0||hand>1||action<0||action>4||!at.IsFinite)return false;if(State==R24LanLobbyState.Hosting){checked{gameCommandSequence++;}return ApplyGrenade(OwnActor,id,hand,action,at);}if(State!=R24LanLobbyState.Connected)return false;using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){Write(w,id,128);w.Write((byte)hand);w.Write((byte)action);w.Write(at.X);w.Write(at.Y);w.Write(at.Z);return QueueGameCommand(GrenadeCommand,m.ToArray());}}
  bool ExplosivePose(string actor,int hand,out R24LanRawTrackingSample raw,out CombatActor inventory,bool allowPaddles=false){raw=null;inventory=null;var member=sessions.Get(actor);var health=member==null?null:hostHealth.Read(member.CanonicalActorId);return InventoryLive&&hand>=0&&hand<=1&&member!=null&&member.Loaded&&member.HasPosition&&health!=null&&health.Connected&&health.Life==LifeState.Alive&&combat.TryGetValue(actor,out inventory)&&Fresh(actor,clock.Now,out raw)&&clock.Now-raw.Time<=.15&&(raw.Pose.Flags&(hand==0?2:4))!=0&&(!raw.Pose.Paddles||allowPaddles);}
  bool ApplyGrenade(string actor,string id,int hand,int action,Float3 at){LastExplosiveRejection="custody-or-pose";R24LanGrenadeState item;R24LanRawTrackingSample raw;CombatActor inventory;if(!grenades.TryGetValue(id,out item)||item.Spent||!ExplosivePose(actor,hand,out raw,out inventory))return false;if(action!=2&&action!=4&&ControlsBlocked(actor))return false;var owner=OwnerGrenades(actor,inventory);var state=owner.State;var tracked=hand==0?raw.Pose.Left:raw.Pose.Right;
   if(action==0){if(!LootAllowed(id)||item.Owner!=""||Distance2(tracked.Position,item.Position)>4||Distance2(raw.Pose.Root.Position,item.Position)>20.25||rawWorldClear==null||!rawWorldClear(raw.Pose.Head.Position,item.Position)||!state.CanStore(item.Kind))return false;R23GrenadeItemState known;if(!state.TryRead(id,out known))state.RegisterWorldCopy(id,item.Kind,1);if(!state.Pickup(id,hand+1,true))return false;PublishGrenade(id,item.Kind,actor,item.Position,false);LastExplosiveRejection=null;return true;}
   if(item.Owner!=actor)return false;if(action==4){state.Stow();LastExplosiveRejection=null;return true;}
   if(action==2){if(!LootAllowed(id)||Distance2(raw.Pose.Root.Position,at)>9||rawWorldClear==null||!rawWorldClear(raw.Pose.Head.Position,at)||!state.Drop(id))return false;PublishGrenade(id,item.Kind,"",at,false);LastExplosiveRejection=null;return true;}
   FoodPreparation food;if(HandOccupied(actor,hand)||foodPreparations.TryGetValue(actor,out food)&&food.Hand==hand)return false;
   if(action==3){bool ok=state.HeldId==id&&state.HeldHand==hand+1||state.Equip(id,hand+1,true);if(ok)LastExplosiveRejection=null;return ok;}
   if(action!=1||projectileWorld==null||projectiles.Count>=64||state.HeldId!=id||state.HeldHand!=hand+1)return false;if(!ThrowableAllowed(item.Kind)){LastExplosiveRejection="rule-disabled";return false;}var basis=GripBasis(tracked);var origin=basis.Point(new Float3(0,.045f,.10f));if(rawWorldClear==null||!rawWorldClear(raw.Pose.Head.Position,origin)){LastExplosiveRejection="launch-world";return false;}R23OwnedGrenade consumed;state.TryThrow(false,true,true,out consumed);if(!state.TryThrow(true,true,true,out consumed)){LastExplosiveRejection="source-equip-cooldown";return false;}var velocity=R23GrenadeMath.LaunchVelocity(basis.Forward,basis.Right,Math.Max(0,origin.Y-raw.Pose.Root.Position.Y));LaunchProjectile(actor,item.Kind,origin,velocity,150);PublishGrenade(id,item.Kind,actor,item.Position,true);LastExplosiveRejection=null;return true;
  }
  public bool RequestRocket(string id,int hand){Check();if(!Wire.IsText(id,128,false)||hand<0||hand>1)return false;if(State==R24LanLobbyState.Hosting){checked{gameCommandSequence++;}MarkGamePrediction(RocketCommand,gameCommandSequence);return ApplyRocket(OwnActor,id,hand);}if(State!=R24LanLobbyState.Connected)return false;using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){Write(w,id,128);w.Write((byte)hand);return QueueGameCommand(RocketCommand,m.ToArray());}}
  bool ApplyRocket(string actor,string id,int hand){LastExplosiveRejection="rocket-custody-or-pose";CombatActor owner;CombatWeapon weapon;R24LanRawTrackingSample raw;if(ControlsBlocked(actor)||!ExplosivePose(actor,hand,out raw,out owner)||!owner.Weapons.TryGetValue(id,out weapon)||weapon.Profile!="smaw"||weapon.Ammo!=1||projectileWorld==null||projectiles.Count>=64||clock.Now-weapon.LastShot<.35||clock.Now-weapon.LastReload<.12)return false;EquippedWeapon equipped;if(!equipment.TryGetValue(actor,out equipped)||equipped.Id!=id||equipped.Hand!=hand||equipped.Suppressed||clock.Now-equipped.At>.5)return false;FoodPreparation food;if(foodPreparations.TryGetValue(actor,out food)&&food.Hand==hand||GrenadeHandOccupied(actor,hand))return false;
   var grip=GripBasis(hand==0?raw.Pose.Left:raw.Pose.Right);var origin=grip.Point(R23WeaponPoseMath.Add(R24SmawRuntime.ModelOffset,R23WeaponPoseMath.Scale(R24SmawRuntime.SourceMuzzle,R24SmawRuntime.ModelScale)));if(rawWorldClear==null||!rawWorldClear(raw.Pose.Head.Position,origin)){LastExplosiveRejection="launch-world";return false;}weapon.Ammo=0;weapon.LastShot=clock.Now;AcceptedShots++;LaunchProjectile(actor,"smaw",origin,R23WeaponPoseMath.Scale(grip.Forward,R24SmawRuntime.RocketSpeed),new float[]{60,84,109,134,160}[weapon.Stars-1]);LastExplosiveRejection=null;return true;
  }
  void LaunchProjectile(string actor,string kind,Float3 origin,Float3 velocity,float power){string id="projectile/"+checked(++projectileIds);var projectile=new Projectile{Id=id,Kind=kind,Actor=actor,Team=sessions.Get(actor).Team,At=origin,Velocity=velocity,Power=power,Time=clock.Now,Clock=kind=="smaw"||kind=="shell"?null:new R23GrenadeClock(id,kind)};projectiles[id]=projectile;PublishProjectile(projectile,false);}
  bool SweepProjectile(Float3 from,Float3 to,out float distance,out Float3 normal){distance=0;normal=new Float3();float range=(float)Math.Sqrt(Distance2(from,to));float native;Float3 n;bool hit=projectileWorld.Sweep(from,to,R23GrenadeMath.CollisionRadius,out native,out n);if(hit&&(Single.IsNaN(native)||native<0||native>range+.001||!n.IsFinite||Distance2(n,new Float3())<.5)){distance=0;normal=new Float3(0,1,0);return true;}distance=hit?native:range;normal=n;var d=Normalize(Sub(to,from));foreach(var panel in sharedPanels.Values)foreach(var box in Ashfall.Modules.ConstructionCandidate.CandidateGeometry.Boxes(panel.Shape)){var half=Ashfall.Modules.ConstructionCandidate.CandidateGeometry.HalfSize(box);var expanded=box;float t=BoxRay(from,d,expanded,range,R23GrenadeMath.CollisionRadius);if(t<=distance){hit=true;distance=t;var at=R23WeaponPoseMath.Add(from,R23WeaponPoseMath.Scale(d,t));var off=Sub(at,box.Center);float x=Math.Abs(Math.Abs(off.X)-half.X),y=Math.Abs(Math.Abs(off.Y)-half.Y),z=Math.Abs(Math.Abs(off.Z)-half.Z);normal=x<=y&&x<=z?new Float3(off.X<0?-1:1,0,0):y<=z?new Float3(0,off.Y<0?-1:1,0):new Float3(0,0,off.Z<0?-1:1);}}if(SweepVehicleProjectile(from,d,range,R23GrenadeMath.CollisionRadius,ref distance,ref normal))hit=true;return hit;}
  static float ProjectileSphereRay(Float3 origin,Float3 direction,Float3 center,float radius){return Distance2(origin,center)<=radius*radius?0:SphereRay(origin,direction,center,radius);}
  void TickExplosives(){if(State!=R24LanLobbyState.Hosting)return;foreach(var pair in grenadeOwners){CombatActor actor;if(combat.TryGetValue(pair.Key,out actor))OwnerGrenades(pair.Key,actor);}var ended=new List<string>();bool publish=clock.Now>=nextProjectiles;if(publish)nextProjectiles=clock.Now+.05;
   foreach(var p in projectiles.Values){double elapsed=Math.Max(0,clock.Now-p.Time);p.Time=clock.Now;if(!InventoryLive)continue;bool done=false;while(elapsed>.000001&&!done){float dt=(float)Math.Min(.02,elapsed);elapsed-=dt;p.Age+=dt;if(p.Clock==null||!p.Clock.Stuck){var velocity=p.Kind=="smaw"?p.Velocity:R23WeaponPoseMath.Add(p.Velocity,new Float3(0,-R23GrenadeMath.Gravity*dt,0));var travel=R23WeaponPoseMath.Scale(velocity,dt);var next=R23WeaponPoseMath.Add(p.At,travel);float distance;Float3 normal;bool hit=SweepProjectile(p.At,next,out distance,out normal);if(p.Kind=="smaw"||p.Kind=="shell"){
      // Host body collision uses the same accepted head/chest/hip volumes as hitscan.
      var direction=Normalize(travel);foreach(var member in sessions.CaptureMembers()){if(member.ActorId==p.Actor)continue;R24LanRawTrackingSample raw;var health=hostHealth.Read(member.CanonicalActorId);if(health==null||health.Life!=LifeState.Alive||!Fresh(member.ActorId,clock.Now,out raw))continue;var head=raw.Pose.Head.Position;float body=Math.Min(ProjectileSphereRay(p.At,direction,head,.205f),Math.Min(ProjectileSphereRay(p.At,direction,new Float3(head.X,head.Y-.45f,head.Z),.325f),ProjectileSphereRay(p.At,direction,new Float3(head.X,head.Y-.92f,head.Z),.305f)));if(body<=distance){distance=body;hit=true;}}
     }
     p.At=R23WeaponPoseMath.Add(p.At,R23WeaponPoseMath.Scale(Normalize(travel),distance));p.Velocity=velocity;if(hit){if(p.Kind=="smaw"||p.Kind=="shell"){BlastProjectile(p,new R23GrenadeBlast(p.Id,p.Kind,0,p.At,p.Kind=="shell"?15:4,p.Power,true));done=true;}else if(p.Kind=="zone"||p.Kind=="smoke"){p.Clock.Contact();p.Velocity=new Float3();p.At=R23WeaponPoseMath.Add(p.At,R23WeaponPoseMath.Scale(normal,.004f));}else{p.At=R23WeaponPoseMath.Add(p.At,R23WeaponPoseMath.Scale(normal,.001f));p.Velocity=R24KnifeMath.Sub(p.Velocity,R23WeaponPoseMath.Scale(normal,Math.Min(0,R23WeaponPoseMath.Dot(p.Velocity,normal))));if(normal.Y>.45f){p.Roll+=distance;p.Velocity=R23GrenadeMath.GroundRollVelocity(p.Velocity,normal,dt,p.Roll);}}}}
     if(p.Clock!=null){p.Clock.Advance(dt,true,p.At,delegate(R23GrenadeBlast blast){BlastProjectile(p,blast);});if(p.Kind=="smoke"&&p.Clock.Active&&!p.Clock.Stuck){p.Clock.Contact();p.Velocity=new Float3();}done=p.Clock.Ended;}else if(!done&&p.Age>=(p.Kind=="smaw"?R24SmawRuntime.ProjectileSeconds:VehicleShellSeconds)){BlastProjectile(p,new R23GrenadeBlast(p.Id,p.Kind,0,p.At,p.Kind=="shell"?15:4,p.Power,true));done=true;}
    }if(done){PublishProjectile(p,true);ended.Add(p.Id);}else if(publish)PublishProjectile(p,false);
   }foreach(string id in ended){projectiles.Remove(id);}
  }
  void BlastProjectile(Projectile projectile,R23GrenadeBlast blast){bool combat=CombatLive;if(!combat&&(projectile.Kind!="shell"||!VehicleBuildDamageLive))return;var losses=new List<KeyValuePair<string,float>>();if(combat)foreach(var member in sessions.CaptureMembers()){R24LanRawTrackingSample raw;if(!Fresh(member.ActorId,clock.Now,out raw))continue;float amount=blast.DamageAt(raw.Pose.Head.Position);if(amount>0)losses.Add(new KeyValuePair<string,float>(member.ActorId,amount));}var panels=new List<KeyValuePair<string,float>>();foreach(var panel in sharedPanels.Values){float amount=0;foreach(var box in Ashfall.Modules.ConstructionCandidate.CandidateGeometry.Boxes(panel.Shape))amount=Math.Max(amount,blast.DamageAt(box.Center));if(amount>0)panels.Add(new KeyValuePair<string,float>(panel.Id,amount));}foreach(var loss in losses)ApplyCombatDamage(projectile.Actor,loss.Key,loss.Value,false,projectile.Team,1,blast.Center);foreach(var panel in panels)DamageSharedPanel(panel.Key,panel.Value);if(combat)foreach(var bike in new List<R25VehicleState>(vehicles.Values))if(!bike.Destroyed)DamageVehicle(bike.Id,blast.DamageAt(VehicleRoot(bike)));}
  void PublishGrenade(string id,string kind,string owner,Float3 at,bool spent){var row=new R24LanGrenadeState(id,kind,owner,at,spent,checked(++grenadeSequence));grenades[id]=row;using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){Write(w,id,128);Write(w,kind,8);w.Write(owner!="");if(owner!="")Write(w,owner,64);w.Write(at.X);w.Write(at.Y);w.Write(at.Z);w.Write(spent);var frame=Packet(PacketKind.Snapshot,GrenadeFeature,OwnActor,m.ToArray(),row.Revision);foreach(var peer in peers.Values)if(peer.Admitted)peer.Grenades[id]=frame;}}
  byte[] ProjectileFrame(R24LanProjectileState row,long sequence){using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){Write(w,row.Id,64);Write(w,row.Kind,8);w.Write(row.Position.X);w.Write(row.Position.Y);w.Write(row.Position.Z);w.Write(row.Velocity.X);w.Write(row.Velocity.Y);w.Write(row.Velocity.Z);w.Write(row.Age);w.Write(row.Radius);w.Write(row.Active);w.Write(row.Ended);if(row.Kind==Ashfall.Integration.Playable.FlashSmoke.R25Throwables.Smoke)w.Write(row.EmitAt);return Packet(PacketKind.Snapshot,ProjectileFeature,OwnActor,m.ToArray(),sequence);}}
  void PublishProjectile(Projectile p,bool ended){var row=new R24LanProjectileState(p.Id,p.Kind,p.At,p.Velocity,p.Clock==null?p.Age:Math.Max(p.Clock.Age,p.Clock.EmitAt),p.Clock==null?0:p.Clock.Radius,p.Clock!=null&&p.Clock.Active,ended,checked(++projectileSequence),p.Clock==null?-1:p.Clock.EmitAt);projectileStates[p.Id]=row;while(projectileStates.Count>128){string oldest=null;long sequence=long.MaxValue;foreach(var pending in projectileStates.Values)if(pending.Ended&&pending.Revision<sequence){oldest=pending.Id;sequence=pending.Revision;}if(oldest==null)break;projectileStates.Remove(oldest);}foreach(var peer in peers.Values)if(peer.Admitted){peer.Projectiles[row.Id]=row;while(peer.Projectiles.Count>128){string oldest=null;long sequence=long.MaxValue;foreach(var pending in peer.Projectiles.Values)if(pending.Ended&&pending.Revision<sequence){oldest=pending.Id;sequence=pending.Revision;}if(oldest==null)break;peer.Projectiles.Remove(oldest);}}}
  // Cosmetic end events have a bounded tail; authoritative damage never depends on its retention.
  public void AcknowledgeProjectilePresentation(R24LanProjectileState row){R24LanProjectileState current;if(row!=null&&row.Ended&&projectileStates.TryGetValue(row.Id,out current)&&Object.ReferenceEquals(row,current))projectileStates.Remove(row.Id);}
  void ReplayExplosives(){foreach(var row in SharedGrenades)PublishGrenade(row.Id,row.Kind,row.Owner,row.Position,row.Spent);foreach(var p in projectiles.Values)PublishProjectile(p,false);}
  void ReadExplosiveCommand(string actor,string feature,byte[] bytes){try{using(var m=new MemoryStream(bytes,false))using(var r=new BinaryReader(m,Utf8)){string id=Read(r,128);int hand=r.ReadByte();if(feature==RocketCommand){if(m.Position==m.Length)ApplyRocket(actor,id,hand);return;}int action=r.ReadByte();var at=new Float3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());if(m.Position==m.Length&&at.IsFinite)ApplyGrenade(actor,id,hand,action,at);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  void ReadGrenade(Packet packet){try{using(var m=new MemoryStream(packet.Payload,false))using(var r=new BinaryReader(m,Utf8)){string id=Read(r,128),kind=Read(r,8),owner=r.ReadBoolean()?Read(r,64):"";var at=new Float3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());bool spent=r.ReadBoolean();R24LanGrenadeState prior;if(m.Position!=m.Length||packet.BaseSequence!=-1||packet.Sequence<1||!R23GrenadeState.ValidKind(kind)||!at.IsFinite||grenades.Count>=4096&&!grenades.ContainsKey(id)||grenades.TryGetValue(id,out prior)&&prior.Revision>=packet.Sequence)return;grenades[id]=new R24LanGrenadeState(id,kind,owner,at,spent,packet.Sequence);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  long receivedProjectileSequence=-1;
  void ReadProjectile(Packet packet){if(packet.Sequence<=receivedProjectileSequence||packet.Sequence<1||packet.BaseSequence!=-1)return;try{using(var m=new MemoryStream(packet.Payload,false))using(var r=new BinaryReader(m,Utf8)){string id=Read(r,64),kind=Read(r,8);var at=new Float3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());var velocity=new Float3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());float age=r.ReadSingle(),radius=r.ReadSingle();bool active=r.ReadBoolean(),ended=r.ReadBoolean();float emitAt=kind==Ashfall.Integration.Playable.FlashSmoke.R25Throwables.Smoke?r.ReadSingle():-1;if(m.Position!=m.Length||!ProjectileEmitValid(kind,emitAt,age)||!at.IsFinite||!velocity.IsFinite||Single.IsNaN(age)||age<0||age>20||Single.IsNaN(radius)||radius<0||radius>15||kind!="shell"&&kind!="smaw"&&!R23GrenadeState.ValidKind(kind)||projectileStates.Count>=128&&!projectileStates.ContainsKey(id))return;receivedProjectileSequence=packet.Sequence;projectileStates[id]=new R24LanProjectileState(id,kind,at,velocity,age,radius,active,ended,packet.Sequence,emitAt);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  void FlushExplosives(string connection,Peer peer){var sent=new List<string>();int budget=16;foreach(var row in peer.Grenades){if(budget--<=0||!Send(connection,row.Value))break;sent.Add(row.Key);}foreach(string id in sent)peer.Grenades.Remove(id);sent.Clear();budget=16;foreach(var row in peer.Projectiles){if(budget--<=0||!Send(connection,ProjectileFrame(row.Value,checked(++peer.ProjectileSequence))))break;sent.Add(row.Key);}foreach(string id in sent)peer.Projectiles.Remove(id);}
 }
